            setError({ kind: 'RATE_LIMITED' });
            setRemainingSeconds(seconds);
            if (seconds > 0) setRetryAt(Date.now() + seconds * 1000);
            break;
          }
150→          case 'INTERNAL_ERROR':
            // RN-8: mensaje no técnico, sin filtrar detalles del error.
            setError({ kind: 'CONNECTION' });
            break;
          default:
            setError({ kind: 'OTHER', code: caught.code });
        }
      } else {
        // Falla de red o respuesta fuera del contrato (RN-8).
        setError({ kind: 'CONNECTION' });
160→      }
    } finally {
      inFlightRef.current = false;
      setSubmitting(false);
    }
  }, [clearNotice, email, password, retryAt, signIn]);

  const onSubmit = useCallback(
    (event: FormEvent<HTMLFormElement>): void => {
      event.preventDefault();
170→      void submit();
    },
    [submit],
  );

  // ------------------------------------------------------------------------- render
  if (state.status === 'checking') {
