  if (state.status === 'authenticated') return <Navigate to={TRADING_ROUTE} replace />;

  return (
    <main className="page page--centered">
190→      <form className="card login" onSubmit={onSubmit} noValidate aria-labelledby="login-title">
        <h1 id="login-title">Ingresar</h1>
        <p className="muted">Exchange ETH/USDC · Sepolia</p>

        {notice === 'SESSION_EXPIRED' && (
          // RN-7: se llegó acá por un `UNAUTHENTICATED` en una llamada protegida.
          <p className="alert alert--warning" role="alert">
            {MESSAGE_SESSION_EXPIRED}
          </p>
        )}
200→        {notice === 'CONNECTION_ERROR' && (
          <p className="alert alert--warning" role="alert">
            {MESSAGE_CONNECTION}
          </p>
        )}

        <label htmlFor="email">Email</label>
        <input
          id="email"
          name="email"
210→          type="email"
          autoComplete="username"
          value={email}
          onChange={(event) => setEmail(event.target.value)}
          aria-invalid={emailIssues.length > 0}
          aria-describedby={emailIssues.length > 0 ? 'email-error' : undefined}
        />
        {emailIssues.length > 0 && (
          <ul className="field-error" id="email-error">
            {emailIssues.map((message) => (
220→              <li key={message}>{message}</li>
            ))}
          </ul>
        )}

        <label htmlFor="password">Contraseña</label>
        <input
          id="password"
          name="password"
          type="password"
230→          autoComplete="current-password"
          value={password}
          onChange={(event) => setPassword(event.target.value)}
          aria-invalid={passwordIssues.length > 0}
          aria-describedby={passwordIssues.length > 0 ? 'password-error' : undefined}
        />
        {passwordIssues.length > 0 && (
          <ul className="field-error" id="password-error">
            {passwordIssues.map((message) => (
              <li key={message}>{message}</li>
240→            ))}
          </ul>
        )}

        <button type="submit" disabled={submitDisabled} aria-busy={submitting}>
          {submitting ? 'Ingresando…' : 'Ingresar'}
        </button>

        {error?.kind === 'CREDENTIALS' && (
          <p className="alert alert--error" role="alert">
250→            {MESSAGE_INVALID_CREDENTIALS}
          </p>
        )}

        {error?.kind === 'VALIDATION' && (
          <div className="alert alert--error" role="alert">
            <p>{messageForCode('VALIDATION_ERROR')}</p>
            {otherIssues.length > 0 && (
              <ul>
                {otherIssues.map((message) => (
260→                  <li key={message}>{message}</li>
                ))}
              </ul>
            )}
          </div>
        )}

        {error?.kind === 'RATE_LIMITED' && (
          <p className="alert alert--error" role="alert">
            {remainingSeconds > 0
270→              ? `Demasiados intentos. Esperá ${remainingSeconds} segundos e intentá de nuevo.`
              : 'Ya podés reintentar.'}
          </p>
        )}

        {error?.kind === 'CONNECTION' && (
          <div className="alert alert--error" role="alert">
            <p>{MESSAGE_CONNECTION}</p>
            {/* RN-8: se ofrece reintentar sin perder el email ingresado. */}
            <button type="button" onClick={() => void submit()} disabled={submitDisabled}>
280→              Reintentar
            </button>
          </div>
        )}

        {error?.kind === 'OTHER' && (
          <p className="alert alert--error" role="alert">
            {messageForCode(error.code)}
          </p>
        )}
290→      </form>
    </main>
  );
}

