1→/**
 * Llamadas de autenticación del contrato de la épica 09 (HU-09-01, mapa de endpoints):
 *   POST /api/v1/auth/login  → 200 { token, expiresAt }   (público, HU-01-02)
 *   GET  /api/v1/me          → 200 { accountId, email, status, createdAt }  (Bearer, HU-01-04)
 */
import { apiRequest } from './client';
import { TransportError } from './errors';

export type Credentials = { email: string; password: string };
10→
/** Sesión emitida por el login (HU-01-02 RN-3: token + `expiresAt` ISO-8601 UTC). */
export type IssuedSession = { token: string; expiresAt: string };

/** Perfil propio (HU-01-04 RN-4: sólo identidad, sin secretos ni montos). */
export type Profile = {
  accountId: string;
  email: string;
  status: string;
  createdAt: string;
20→};

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/**
 * Inicia sesión. El email se envía tal como lo tipeó el usuario: la normalización
 * (`trim` + `lowercase`) es del servidor (HU-01-02 RN-1), que es la única fuente de verdad
 * (RNE-2). El cliente tampoco valida el formato del email antes de enviar: hacerlo
30→ * distinguiría "formato inválido" de "inexistente" y filtraría información (HU-01-02 RN-11).
 */
export async function login(credentials: Credentials): Promise<IssuedSession> {
  const payload = await apiRequest<unknown>('/auth/login', {
    method: 'POST',
    body: { email: credentials.email, password: credentials.password },
  });
  if (
    !isPlainObject(payload) ||
    typeof payload.token !== 'string' ||
40→    payload.token === '' ||
    typeof payload.expiresAt !== 'string' ||
    Number.isNaN(Date.parse(payload.expiresAt))
  ) {
    // Un 200 sin token utilizable no es una sesión: no se asume éxito (RNE-2).
    throw new TransportError('la respuesta de login no incluye un token utilizable');
  }
  return { token: payload.token, expiresAt: payload.expiresAt };
}

50→/**
 * Perfil a partir del cuerpo de un `GET /me` exitoso, o `null` si el cuerpo no respeta el
 * contrato de HU-09-01 (mapa de endpoints: `{ accountId, email, status, createdAt }`).
 *
 * Devuelve `null` en vez de lanzar porque la **validez de la sesión** y la **forma del
 * perfil** son decisiones distintas: RN-11 es explícita en que un 200 significa sesión
 * válida. Un cuerpo incompleto sólo deja al cliente sin datos que mostrar.
 */
export function parseProfile(payload: unknown): Profile | null {
  if (
60→    !isPlainObject(payload) ||
    typeof payload.accountId !== 'string' ||
    typeof payload.email !== 'string' ||
    typeof payload.status !== 'string' ||
    typeof payload.createdAt !== 'string'
  ) {
    return null;
  }
  return {
    accountId: payload.accountId,
70→    email: payload.email,
    status: payload.status,
    createdAt: payload.createdAt,
  };
}

/**
 * Validación liviana de la sesión (HU-10-01 RN-11): `GET /me` con el token persistido.
 *
 * **200 ⇒ sesión válida**, tal como lo exige RN-11, aunque el cuerpo no traiga todos los
80→ * campos del perfil: en ese caso resuelve con `profile: null` y la sesión sigue en pie. Sólo
 * invalidan la sesión el `UNAUTHENTICATED` (401) —que llega como `ApiError` y limpia el
 * llamador—, la ausencia del token o su expiración local.
 */
export async function fetchProfile(
  token: string,
  signal?: AbortSignal,
): Promise<{ profile: Profile | null }> {
  const payload = await apiRequest<unknown>('/me', signal === undefined ? { token } : { token, signal });
  return { profile: parseProfile(payload) };
90→}

