1→/**
 * Estado de sesión de la SPA (HU-10-01 RN-3, RN-7, RN-9, RN-11).
 *
 * - Mantiene el token en memoria y lo persiste junto con su `expiresAt` (RN-3).
 * - Al cargar la app revalida el token persistido con `GET /me` (RN-11): 200 ⇒ sesión válida;
 *   `UNAUTHENTICATED` (401), token ausente o expirado según su expiración registrada ⇒ se
 *   limpia todo el estado local y se permanece en login.
 * - Expone `authorizedFetch`, que ante `UNAUTHENTICATED` en **cualquier** llamada protegida
 *   limpia la sesión y deja el aviso de "sesión expirada" (RN-7 / RNE-4). La redirección a
10→ *   login la hace `RequireSession` al ver el estado anónimo.
 *
 * El token nunca se expone en la UI ni se registra en logs (RNE-4): sale de acá sólo hacia el
 * header `Authorization`.
 */
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
20→  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import { fetchProfile, type IssuedSession, type Profile } from '../api/auth';
import { apiRequest, type RequestOptions } from '../api/client';
import { ApiError } from '../api/errors';
import { clearSession, isExpired, loadSession, saveSession } from './storage';

30→/** Aviso que la pantalla de login muestra cuando la sesión terminó fuera de ella. */
export type SessionNotice = 'SESSION_EXPIRED' | 'CONNECTION_ERROR';

export type SessionState =
  /** Revalidando el token persistido contra `GET /me` (RN-11). */
  | { status: 'checking' }
  | { status: 'anonymous' }
  | { status: 'authenticated'; token: string; expiresAt: string; profile: Profile | null };

export type SessionContextValue = {
40→  state: SessionState;
  notice: SessionNotice | null;
  /** Establece la sesión tras un login exitoso y la persiste (RN-3). */
  signIn: (session: IssuedSession, profile?: Profile | null) => void;
  clearNotice: () => void;
  /** Llamada protegida: adjunta el Bearer y aplica RN-7 ante `UNAUTHENTICATED`. */
  authorizedFetch: <T>(path: string, options?: Omit<RequestOptions, 'token'>) => Promise<T>;
};

const SessionContext = createContext<SessionContextValue | null>(null);
50→
export function SessionProvider({ children }: { children: ReactNode }): React.JSX.Element {
  const [state, setState] = useState<SessionState>({ status: 'checking' });
  const [notice, setNotice] = useState<SessionNotice | null>(null);
  // El token también vive en un ref para que `authorizedFetch` no dependa del closure del
  // render en el que se creó.
  const tokenRef = useRef<string | null>(null);

  const applyAnonymous = useCallback((nextNotice: SessionNotice | null) => {
    tokenRef.current = null;
60→    clearSession();
    setState({ status: 'anonymous' });
    if (nextNotice !== null) setNotice(nextNotice);
  }, []);

  // ------------------------------------------------------------------ bootstrap (RN-11)
  useEffect(() => {
    const controller = new AbortController();
    let cancelled = false;

70→    const persisted = loadSession();
    if (persisted === null || isExpired(persisted.expiresAt)) {
      // Token ausente o expirado según su expiración registrada: se limpia y se permanece
      // en login, sin gastar una llamada al servidor (RN-11).
      tokenRef.current = null;
      clearSession();
      setState({ status: 'anonymous' });
      return () => {
        cancelled = true;
        controller.abort();
80→      };
    }

    tokenRef.current = persisted.token;
    void (async () => {
      try {
        // 200 ⇒ sesión válida (RN-11). El perfil puede venir incompleto (`null`): eso no
        // invalida la sesión, sólo deja a la UI sin datos que mostrar.
        const { profile } = await fetchProfile(persisted.token, controller.signal);
        if (cancelled) return;
90→        setState({
          status: 'authenticated',
          token: persisted.token,
          expiresAt: persisted.expiresAt,
          profile,
        });
      } catch (error) {
        if (cancelled) return;
        if (error instanceof ApiError && error.code === 'UNAUTHENTICATED') {
          // Token inválido, expirado del lado del servidor o revocado: se limpia todo el
100→          // estado de sesión local y se muestra el formulario de login (RN-11, AT-10-01-10).
          // Sin aviso de "sesión expiró": el usuario no venía de una sesión activa en esta
          // navegación, ese aviso es el de RN-7.
          applyAnonymous(null);
          return;
        }
        if (error instanceof DOMException && error.name === 'AbortError') return;
        // No se pudo validar por red/servidor: el servidor es la única fuente de verdad
        // (RNE-2), así que no se asume una sesión válida; pero tampoco se descarta el token
        // persistido, porque RN-11 sólo lo descarta ante 401, ausencia o expiración local.
110→        tokenRef.current = null;
        setState({ status: 'anonymous' });
        setNotice('CONNECTION_ERROR');
      }
    })();

    return () => {
      cancelled = true;
      controller.abort();
    };
120→  }, [applyAnonymous]);

  // --------------------------------------------------------------------------- acciones
  const signIn = useCallback((session: IssuedSession, profile: Profile | null = null) => {
    tokenRef.current = session.token;
    saveSession({ token: session.token, expiresAt: session.expiresAt });
    setNotice(null);
    setState({
      status: 'authenticated',
      token: session.token,
130→      expiresAt: session.expiresAt,
      profile,
    });
  }, []);

