1→/**
 * Cliente HTTP del contrato de la épica 09.
 *
 * Responsabilidades:
 *  - componer la URL sobre la ruta base `/api/v1` (HU-09-01 RN-1);
 *  - enviar `Content-Type: application/json` en las requests con cuerpo (HU-09-01 RN-3);
 *  - presentar la credencial como `Authorization: Bearer <token>` (HU-09-02 RN-1). El
 *    contrato **no** usa cookies de sesión (HU-10-01 RN-3), por eso no se envían
 *    credenciales de navegador (`credentials: 'omit'`);
10→ *  - traducir toda respuesta de error al `ApiError` del catálogo y cualquier otra falla a
 *    `TransportError`.
 *
 * El token nunca se registra en logs ni se incluye en mensajes de error (RNE-4).
 */
import { API_BASE_URL } from '../config';
import { ApiError, TransportError, isErrorCode } from './errors';

export type RequestOptions = {
  method?: 'GET' | 'POST' | 'DELETE';
20→  body?: unknown;
  /** Token Bearer para recursos protegidos (HU-09-02 RN-1). */
  token?: string;
  signal?: AbortSignal;
};

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

30→/**
 * Ejecuta una llamada al contrato y devuelve el cuerpo parseado.
 *
 * Lanza `ApiError` si la respuesta trae el envelope de error del catálogo, y `TransportError`
 * si no hubo respuesta o la respuesta no respeta el contrato.
 */
export async function apiRequest<T>(path: string, options: RequestOptions = {}): Promise<T> {
  const { method = 'GET', body, token, signal } = options;

  const headers: Record<string, string> = { Accept: 'application/json' };
40→  if (body !== undefined) headers['Content-Type'] = 'application/json';
  if (token !== undefined) headers.Authorization = `Bearer ${token}`;

  let response: Response;
  try {
    const init: RequestInit = {
      method,
      headers,
      credentials: 'omit',
      ...(body === undefined ? {} : { body: JSON.stringify(body) }),
50→      ...(signal === undefined ? {} : { signal }),
    };
    response = await fetch(`${API_BASE_URL}${path}`, init);
  } catch (error) {
    // Red caída, DNS, CORS, aborto: no hay respuesta del servidor (HU-10-01 RN-8).
    if (error instanceof DOMException && error.name === 'AbortError') throw error;
    throw new TransportError('la solicitud no llegó al servidor');
  }

  const payload = await readJson(response);
60→
  if (!response.ok) {
    const envelope = isPlainObject(payload) ? payload.error : undefined;
    if (isPlainObject(envelope) && isErrorCode(envelope.code)) {
      const details = isPlainObject(envelope.details) ? envelope.details : {};
      throw new ApiError(envelope.code, response.status, details, retryAfterHeader(response));
    }
    // Respuesta de error que no respeta el envelope del catálogo (p. ej. un 502 HTML de un
    // proxy). No se inventa un `code`: se trata como falla de transporte.
    throw new TransportError(`respuesta de error fuera del contrato (HTTP ${response.status})`);
70→  }

  if (response.status === 204) return undefined as T;
  if (payload === undefined) throw new TransportError('respuesta exitosa sin cuerpo JSON válido');
  return payload as T;
}

/**
 * Header `Retry-After` en segundos (respaldo de `details.retryAfterSeconds`, HU-09-02 RN-12).
 * Sólo se acepta la forma de conteo entero: la variante con fecha HTTP no la usa el contrato.
80→ */
function retryAfterHeader(response: Response): number | null {
  const raw = response.headers.get('Retry-After');
  if (raw === null) return null;
  const parsed = Number(raw.trim());
  return Number.isInteger(parsed) && parsed >= 0 ? parsed : null;
}

async function readJson(response: Response): Promise<unknown> {
  let text: string;
90→  try {
    text = await response.text();
  } catch {
    return undefined;
  }
  if (text === '') return undefined;
  try {
    return JSON.parse(text) as unknown;
  } catch {
    return undefined;
100→  }
}

