 *
 * Al superar el umbral se responde `RATE_LIMITED` (429) con `details.retryAfterSeconds`
10→ * (entero ≥ 0: segundos que faltan para que la solicitud más antigua salga de la ventana)
 * y header `Retry-After`.
 */
export type RateLimitDecision =
  | { allowed: true }
  | { allowed: false; retryAfterSeconds: number };

export class SlidingWindowRateLimiter {
  private readonly hits = new Map<string, number[]>();

20→  constructor(
    private readonly max: number,
    private readonly windowMs: number,
  ) {}

  /** Poda las marcas fuera de la ventana y devuelve las vigentes. */
  private current(key: string, now: number): number[] {
    const timestamps = this.hits.get(key);
    if (timestamps === undefined) return [];
    const cutoff = now - this.windowMs;
30→    const fresh = timestamps.filter((t) => t > cutoff);
    if (fresh.length === 0) this.hits.delete(key);
    else this.hits.set(key, fresh);
    return fresh;
