const authenticate = async (request: FastifyRequest): Promise<void> => {
  const header = request.headers.authorization;
  if (header === undefined) throw new AppError('UNAUTHENTICATED', 'Falta la credencial de sesión.');
  const match = /^Bearer (.+)$/.exec(header.trim());
  if (match === null) {
    throw new AppError('UNAUTHENTICATED', 'Credencial ausente, inválida o expirada.');
  }
  const session = deps.sessions.resolve(match[1] as string);
  if (session === null) {
    throw new AppError('UNAUTHENTICATED', 'Credencial ausente, inválida o expirada.');
  }
  request.accountId = session.accountId;
  // El logout necesita el token **presentado** para revocarlo (HU-01-03 RN-1/RN-5): se
  // guarda acá para no volver a parsear el header en el handler. No se registra en logs ni
  // se serializa en ninguna respuesta (RN-9).
  request.sessionToken = match[1] as string;
};

/** Rate limiting por cuenta y endpoint para recursos autenticados (HU-09-02 RN-12). */
const accountRateLimit = async (request: FastifyRequest): Promise<void> => {
  const key = `${request.accountId}:${normalizePath(request.url)}`;
  const decision = accountLimiter.consume(key);
  if (!decision.allowed) throw rateLimited(decision.retryAfterSeconds);
};

// --------------------------------------------------------------------------- rutas
app.post(
  '/api/v1/auth/register',
  {
    onRequest: async (request) => {
      // Paso 0 de la precedencia (HU-01-01 RN-9/RN-10): el rate limiting por origen se
      // evalúa antes que cualquier otra validación, incluso la de esquema.
      const origin = clientOrigin(request);
      const decision = registerLimiter.consume(origin);
      if (!decision.allowed) {
        deps.audit.record({
          event: 'REGISTER',
          email: null,
          result: 'FAILURE',
          reason: 'RATE_LIMITED',
          origin,
        });
        throw rateLimited(decision.retryAfterSeconds);
      }
    },
  },
  async (request, reply) => {
    const account = await deps.accounts.register(request.body, clientOrigin(request));
    reply.status(201).send(account);
  },
);

app.post(
  '/api/v1/auth/login',
  {
    onRequest: async (request) => {
      // Paso 0 (HU-01-02 RN-9): se limita por origen en función de los intentos **fallidos**
      // acumulados; los intentos exitosos no cuentan ni reinician la ventana.
      const origin = clientOrigin(request);
      const decision = loginFailureLimiter.check(origin);
      if (!decision.allowed) {
        // RNE-9 enumera `RATE_LIMITED` como `reason` posible: el intento rechazado por rate
        // limiting también es un intento de autenticación y se audita. El email todavía no
        // se conoce (el rechazo ocurre antes de parsear el cuerpo, como exige el paso 0).
        deps.audit.record({
          event: 'LOGIN',
          email: null,
          result: 'FAILURE',
          reason: 'RATE_LIMITED',
          origin,
        });
        throw rateLimited(decision.retryAfterSeconds);
      }
    },
  },
  async (request, reply) => {
    const origin = clientOrigin(request);
    try {
      const session = await deps.accounts.login(request.body, origin);
      reply.status(200).send(session);
    } catch (error) {
      if (error instanceof AppError && error.code === 'INVALID_CREDENTIALS') {
        loginFailureLimiter.record(origin);
      }
      throw error;
    }
  },
);

