 *
 * Mientras se revalida el token persistido (`GET /me`, HU-10-01 RN-11) no se decide nada. Sin
 * sesión, se redirige a la pantalla de login: es el camino por el que se materializa RN-7
 * (un `UNAUTHENTICATED` en una llamada protegida limpia la sesión ⇒ el estado pasa a anónimo
 * ⇒ acá se redirige, y login muestra el aviso de sesión expirada).
 */
import type { ReactNode } from 'react';
import { Navigate } from 'react-router-dom';
import { useSession } from '../session/SessionProvider';
import { LOGIN_ROUTE } from './routes';

export function RequireSession({ children }: { children: ReactNode }): React.JSX.Element {
  const { state } = useSession();
  if (state.status === 'checking') {
    return (
      <main className="page page--centered">
        <p role="status">Validando sesión…</p>
      </main>
    );
  }
  if (state.status === 'anonymous') return <Navigate to={LOGIN_ROUTE} replace />;
  return <>{children}</>;
}

