async (page) => {
  await page.unrouteAll({ behavior: 'ignoreErrors' }).catch(() => {});
  await page.evaluate(() => localStorage.removeItem('exchange.web.session.v1'));

  let release;
  const gate = new Promise((resolve) => { release = resolve; });
  let meSeen = 0;
  await page.route('**/api/v1/me', async (route) => {
    if (route.request().method() !== 'GET') {
      await route.continue();
      return;
    }
    meSeen += 1;
    await gate;
    await route.continue();
  });

  await page.goto('http://127.0.0.1:4201/login');
  await page.getByRole('textbox', { name: 'Email' }).fill('eval-web@test.local');
  await page.getByRole('textbox', { name: 'Contrase\u00f1a' }).fill('EvalWeb123!');
  await page.getByRole('button', { name: 'Ingresar' }).click();
  await page.waitForURL('**/trading', { timeout: 20000 });

  const session = await page.evaluate(() => {
    const raw = localStorage.getItem('exchange.web.session.v1');
    return raw ? JSON.parse(raw) : null;
  });
  if (!session || !session.token) {
    return { error: 'no token after login', meSeen, url: page.url() };
  }

  const logoutRes = await page.evaluate(async (token) => {
    const res = await fetch('http://127.0.0.1:3201/api/v1/auth/logout', {
      method: 'POST',
      headers: { Authorization: 'Bearer ' + token, accept: 'application/json' },
    });
    return { status: res.status, body: await res.text() };
  }, session.token);

  const meResponses = [];
  const handler = async (res) => {
    if (res.url().includes('/api/v1/me')) {
      let body = null;
      try { body = await res.json(); } catch (e) { body = await res.text(); }
      meResponses.push({ status: res.status(), body });
    }
  };
  page.on('response', handler);

  release();
  await page.waitForURL('**/login', { timeout: 20000 });
  await page.waitForTimeout(400);
  await page.screenshot({ path: 'evidencia/AT-10-01-07-1.png', fullPage: true, scale: 'css' });
  page.off('response', handler);

  const after = await page.evaluate(() => ({
    url: location.href,
    storage: localStorage.getItem('exchange.web.session.v1'),
    alerts: Array.from(document.querySelectorAll('[role=alert]')).map((el) => el.innerText),
    hasEmail: Boolean(document.querySelector('#email')),
    heading: document.querySelector('h1') && document.querySelector('h1').textContent,
    bodyText: document.body.innerText.slice(0, 600),
  }));

  await page.unrouteAll({ behavior: 'ignoreErrors' }).catch(() => {});
  return { meSeen, logoutRes, meResponses, after, tokenPrefix: session.token.slice(0, 8) };
}

